{"id":"R0014","key":"compute_radio","s":"OBSERVED","f":"Indoor testbed uses 24 Jetson computers over WiFi; outdoor test uses five UAVs with Jetson boards over ad-hoc modules.","l":[[10,"VIII.A Evaluation Setup","deployed ASAP on 24 UAV airborne computers"],[11,"VIII.A Evaluation Setup","transmit data through the Ad hoc modules"]],"g":null}
